 {view==='orders'&&<><div className="flex justify-between"><h2 className="text-lg font-semibold">Orders</h2><button onClick={()=>void loadOrders()} className="text-sm underline">Refresh</button></div><div className="bg-white border rounded-xl overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-100"><tr><th className="p-3 text-left">Order</th><th className="p-3 text-left">Date</th><th className="p-3 text-left">Order Status</th><th className="p-3 text-left">Payment</th><th className="p-3 text-left">Total</th><th className="p-3">Action</th></tr></thead><tbody>{orders.map(o=><tr key={o.id} className="border-t"><td className="p-3">{o.order_number}</td><td className="p-3">{new Date(o.created_at).toLocaleDateString()}</td><td className="p-3">{o.order_status}</td><td className="p-3">{o.payment_status}</td><td className="p-3">RM {Number(o.total_myr).toFixed(2)}</td><td className="p-3">{o.order_status==='processing'&&can('shipments.manage')&&<button onClick={()=>void createShipment(o)} className="underline">Create shipment</button>}{o.order_status==='shipped'&&can('orders.complete')&&<button onClick={async()=>{const reason=window.prompt('Completion reason:');if(!reason?.trim())return;const{error}=await supabase.rpc('admin_complete_order',{p_order_id:o.id,p_reason:reason});if(error)setError(error.message);else await loadOrders();}} className="underline">Mark completed</button>}</td></tr>)}</tbody></table></div></>}
